class Profile:
    __slots__ = ("_user_id", "_fields")

    def __init__(self, user_id, fields):
        if not isinstance(user_id, str) or not user_id:
            raise ValueError("user_id boş olmayan mətn olmalıdır")
        object.__setattr__(self, "_user_id", user_id)
        object.__setattr__(self, "_fields", dict(fields))

    def __setattr__(self, name, value):
        if name == "_user_id" and hasattr(self, "_user_id"):
            raise AttributeError("user_id yaradıldıqdan sonra dəyişmir")
        object.__setattr__(self, name, value)

    @property
    def user_id(self):
        return self._user_id

    def __str__(self):
        return f"{self._fields.get('name', 'Adsız')} ({len(self)} sahə)"

    def __repr__(self):
        return f"Profile(user_id={self._user_id!r}, fields={self._fields!r})"

    def __len__(self):
        return len(self._fields)

    def __getitem__(self, key):
        return self._fields[key]

    def __setitem__(self, key, value):
        self._fields[key] = value

    def __delitem__(self, key):
        del self._fields[key]

    def __iter__(self):
        return iter(self._fields)

    def __contains__(self, key):
        return key in self._fields

    def __bool__(self):
        return bool(self._fields)

    def __call__(self, bonus=0):
        return self._fields.get("score", 0) + bonus

    def __eq__(self, other):
        if not isinstance(other, Profile):
            return NotImplemented
        return self._user_id == other._user_id

    def __hash__(self):
        return hash(self._user_id)

    def __enter__(self):
        return self

    def __exit__(self, exception_type, exception, traceback):
        return False


def main():
    profile = Profile("u-17", {"name": "Aylin", "score": 90})
    print(str(profile))
    print(repr(profile))
    print(len(profile), profile["name"])
    profile["city"] = "Baku"
    print("name" in profile, list(profile), bool(profile))
    print("hesab:", profile(bonus=5))
    with profile as active:
        active["score"] += 1
    del profile["city"]
    same_user = Profile("u-17", {"name": "Başqa", "score": 10})
    print(profile["score"], profile == same_user, len({profile, same_user}))

if __name__ == "__main__":
    main()

class Measurement:
    def __init__(self, value, unit):
        if value < 0:
            raise ValueError("Ölçü mənfi ola bilməz")
        self.value = value
        self.unit = unit

    def __repr__(self):
        return f"Measurement({self.value!r}, {self.unit!r})"

    def __eq__(self, other):
        if not isinstance(other, Measurement):
            return NotImplemented
        return self.value == other.value and self.unit == other.unit

    def __lt__(self, other):
        if not isinstance(other, Measurement):
            return NotImplemented
        if self.unit != other.unit:
            raise ValueError("Fərqli vahidləri birbaşa müqayisə etmək olmaz")
        return self.value < other.value


def main():
    room = Measurement(21, "C")
    target = Measurement(24, "C")
    same_room = Measurement(21, "C")
    print(room)
    print(room == same_room)
    print(room < target)


if __name__ == "__main__":
    main()
